.segment "CODE"
; ---------------------------------------------------------------------------
; Math Runtime Routines
; __ADD16_AX: right operand (word) in A/X
__ADD16_AX:
	STA __MATH1
	STX __MATH1+1
; __ADD16: 16-bit addition (accumulator style)
; Input: __MATH0 low word (left operand), __MATH1 low word (right operand)
; Output: __MATH0=sum (32-bit, high word cleared)
__ADD16:
	LDA __MATH0
	CLC
	ADC __MATH1
	STA __MATH0
	LDA __MATH0+1
	ADC __MATH1+1
	STA __MATH0+1
	STZ __MATH0+2
	STZ __MATH0+3
	RTS
; ADD32: __MATH0 = __MATH0 + __MATH1
ADD32:
	LDA __MATH0
	CLC
	ADC __MATH1
	STA __MATH0
	LDA __MATH0+1
	ADC __MATH1+1
	STA __MATH0+1
	LDA __MATH0+2
	ADC __MATH1+2
	STA __MATH0+2
	LDA __MATH0+3
	ADC __MATH1+3
	STA __MATH0+3
	RTS
